// Package clock is the source of time for everything under internal/.
package clock

import "time"

// Clock tells the time.
type Clock interface {
	Now() time.Time
}

// Real is the system clock.
type Real struct{}

// Now returns the current time.
func (Real) Now() time.Time { return time.Now() }

// Fixed is a clock stopped at a time, for tests.
type Fixed struct{ T time.Time }

// Now returns the fixed time.
func (f Fixed) Now() time.Time { return f.T }
// Package id makes identifiers.
package id

import (
	"crypto/rand"
	"encoding/hex"
)

// New returns a random 128-bit identifier as 32 hex characters.
func New() string {
	var b [16]byte
	rand.Read(b[:])
	return hex.EncodeToString(b[:])
}
// Package log is the project's structured logger. Everything under internal/
// logs through it.
package log

import (
	"log/slog"
	"os"
)

var logger = slog.New(slog.NewTextHandler(os.Stderr, nil))

// Info logs an informational message with key-value pairs.
func Info(msg string, kv ...any) { logger.Info(msg, kv...) }

// Warn logs a warning with key-value pairs.
func Warn(msg string, kv ...any) { logger.Warn(msg, kv...) }

// Error logs an error with key-value pairs.
func Error(msg string, kv ...any) { logger.Error(msg, kv...) }
