// Package billing computes invoices.
package billing

import (
	"fmt"
	"time"

	"example.com/app/internal/clock"
	"example.com/app/internal/id"
)

// Line is one line of an invoice.
type Line struct {
	SKU       string `json:"sku"`
	Quantity  int    `json:"quantity"`
	UnitCents int64  `json:"unit_cents"`
}

// Invoice is a computed invoice. TotalCents is the sum of the lines,
// DiscountCents is taken off it, TaxCents is charged on the discounted total
// and GrandTotalCents is the amount due.
type Invoice struct {
	ID              string    `json:"id"`
	Customer        string    `json:"customer"`
	Region          string    `json:"region"`
	Lines           []Line    `json:"lines"`
	TotalCents      int64     `json:"total_cents"`
	DiscountCode    string    `json:"discount_code"`
	DiscountCents   int64     `json:"discount_cents"`
	TaxCents        int64     `json:"tax_cents"`
	GrandTotalCents int64     `json:"grand_total_cents"`
	IssuedAt        time.Time `json:"issued_at"`
}

// Calculator computes invoices with discounts and regional tax.
type Calculator struct {
	clock clock.Clock
	rates TaxTable
	usage *Usage
}

// NewCalculator returns a Calculator. The rates table is read, never changed.
func NewCalculator(c clock.Clock, rates TaxTable, usage *Usage) *Calculator {
	return &Calculator{clock: c, rates: rates, usage: usage}
}

// Invoice builds an invoice for a customer in a region. An empty id is
// replaced by a generated one. At most one discount may be given; pass nil for
// none. The discount is recorded as used only when the invoice is built.
func (c *Calculator) Invoice(invID, customer, region string, lines []Line, d *Discount) (Invoice, error) {
	if customer == "" {
		return Invoice{}, ErrNoCustomer
	}
	if invID == "" {
		invID = id.New()
	}
	var total int64
	for i, l := range lines {
		if l.Quantity < 0 || l.UnitCents < 0 {
			return Invoice{}, fmt.Errorf("%w: line %d (%s): quantity %d, unit %d", ErrInvalidLine, i, l.SKU, l.Quantity, l.UnitCents)
		}
		total += int64(l.Quantity) * l.UnitCents
	}
	now := c.clock.Now()
	inv := Invoice{ID: invID, Customer: customer, Region: region, Lines: lines, TotalCents: total, IssuedAt: now}

	if d != nil {
		if err := d.validate(); err != nil {
			return Invoice{}, err
		}
		if !d.ExpiresAt.IsZero() && !now.Before(d.ExpiresAt) {
			return Invoice{}, fmt.Errorf("%w: code %s expired at %s", ErrDiscountExpired, d.Code, d.ExpiresAt.Format(time.RFC3339))
		}
		if c.usage.Used(d.Code, customer) {
			return Invoice{}, fmt.Errorf("%w: code %s, customer %s", ErrDiscountUsed, d.Code, customer)
		}
		inv.DiscountCode = d.Code
		inv.DiscountCents = d.amount(total)
	}

	tax, err := c.rates.Tax(region, total-inv.DiscountCents)
	if err != nil {
		return Invoice{}, fmt.Errorf("compute tax for invoice %s: %w", invID, err)
	}
	inv.TaxCents = tax
	inv.GrandTotalCents = total - inv.DiscountCents + tax

	if d != nil && !c.usage.claim(d.Code, customer) {
		return Invoice{}, fmt.Errorf("%w: code %s, customer %s", ErrDiscountUsed, d.Code, customer)
	}
	return inv, nil
}

// Compute builds an invoice for a customer with no discount and no tax. It
// returns the zero Invoice if the customer is empty or a line is invalid. New
// code should use Calculator.Invoice.
func Compute(id, customer string, lines []Line) Invoice {
	c := NewCalculator(clock.Real{}, TaxTable{"": 0}, NewUsage())
	inv, err := c.Invoice(id, customer, "", lines, nil)
	if err != nil {
		return Invoice{}
	}
	return inv
}

// Describe returns a one-line summary of an invoice.
func Describe(inv Invoice) string {
	return fmt.Sprintf("%s %s %d.%02d", inv.ID, inv.Customer, inv.TotalCents/100, inv.TotalCents%100)
}

// Meta holds free-form invoice metadata.
type Meta map[string]any

