package billing

import (
	"bytes"
	"context"
	"errors"
	"strings"
	"testing"
	"time"

	"example.com/app/internal/clock"
)

var testNow = time.Date(2026, 3, 1, 12, 0, 0, 0, time.UTC)

func newCalc() *Calculator {
	rates := TaxTable{"FR": 2000, "DE": 1900, "US-CA": 725, "ZERO": 0}
	return NewCalculator(clock.Fixed{T: testNow}, rates, NewUsage())
}

func TestCompute(t *testing.T) {
	inv := Compute("inv1", "acme", []Line{{SKU: "a", Quantity: 2, UnitCents: 150}, {SKU: "b", Quantity: 1, UnitCents: 99}})
	if inv.TotalCents != 399 {
		t.Errorf("Compute total = %d, want 399", inv.TotalCents)
	}
	if inv.GrandTotalCents != 399 {
		t.Errorf("Compute grand total = %d, want 399", inv.GrandTotalCents)
	}
	if got := Compute("x", "", nil); got.ID != "" {
		t.Errorf("Compute with no customer = %+v, want zero Invoice", got)
	}
	if got, want := Describe(inv), "inv1 acme 3.99"; got != want {
		t.Errorf("Describe = %q, want %q", got, want)
	}
}

func TestInvoiceDiscount(t *testing.T) {
	lines := []Line{{SKU: "a", Quantity: 1, UnitCents: 1000}}
	past := testNow.Add(-time.Hour)
	future := testNow.Add(time.Hour)
	tests := []struct {
		name      string
		lines     []Line
		d         *Discount
		wantDisc  int64
		wantGrand int64
		wantErr   error
	}{
		{"none", lines, nil, 0, 1000, nil},
		{"percent", lines, &Discount{Code: "P10", Kind: DiscountPercent, Value: 1000}, 100, 900, nil},
		{"percent rounds half up", []Line{{SKU: "a", Quantity: 1, UnitCents: 15}}, &Discount{Code: "P10", Kind: DiscountPercent, Value: 1000}, 2, 13, nil},
		{"percent rounds down", []Line{{SKU: "a", Quantity: 1, UnitCents: 14}}, &Discount{Code: "P10", Kind: DiscountPercent, Value: 1000}, 1, 13, nil},
		{"percent 100", lines, &Discount{Code: "ALL", Kind: DiscountPercent, Value: 10000}, 1000, 0, nil},
		{"fixed", lines, &Discount{Code: "F5", Kind: DiscountFixed, Value: 500}, 500, 500, nil},
		{"fixed floors at zero", lines, &Discount{Code: "F99", Kind: DiscountFixed, Value: 9900}, 1000, 0, nil},
		{"empty invoice", nil, &Discount{Code: "F5", Kind: DiscountFixed, Value: 500}, 0, 0, nil},
		{"expiry in future", lines, &Discount{Code: "E", Kind: DiscountFixed, Value: 100, ExpiresAt: future}, 100, 900, nil},
		{"expired", lines, &Discount{Code: "E", Kind: DiscountFixed, Value: 100, ExpiresAt: past}, 0, 0, ErrDiscountExpired},
		{"expires exactly now", lines, &Discount{Code: "E", Kind: DiscountFixed, Value: 100, ExpiresAt: testNow}, 0, 0, ErrDiscountExpired},
		{"percent over 100", lines, &Discount{Code: "B", Kind: DiscountPercent, Value: 10001}, 0, 0, ErrInvalidDiscount},
		{"negative fixed", lines, &Discount{Code: "B", Kind: DiscountFixed, Value: -1}, 0, 0, ErrInvalidDiscount},
		{"unknown kind", lines, &Discount{Code: "B", Kind: "weird", Value: 1}, 0, 0, ErrInvalidDiscount},
		{"empty code", lines, &Discount{Kind: DiscountFixed, Value: 1}, 0, 0, ErrInvalidDiscount},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			inv, err := newCalc().Invoice("i", "acme", "ZERO", tt.lines, tt.d)
			if !errors.Is(err, tt.wantErr) {
				t.Fatalf("Invoice(%s) error = %v, want %v", tt.name, err, tt.wantErr)
			}
			if err != nil {
				return
			}
			if inv.DiscountCents != tt.wantDisc || inv.GrandTotalCents != tt.wantGrand {
				t.Errorf("Invoice(%s) discount, grand = %d, %d; want %d, %d", tt.name, inv.DiscountCents, inv.GrandTotalCents, tt.wantDisc, tt.wantGrand)
			}
		})
	}
}

func TestDiscountReuse(t *testing.T) {
	c := newCalc()
	lines := []Line{{SKU: "a", Quantity: 1, UnitCents: 1000}}
	d := &Discount{Code: "ONCE", Kind: DiscountFixed, Value: 100}
	steps := []struct {
		name     string
		customer string
		wantErr  error
	}{
		{"first use", "acme", nil},
		{"same customer again", "acme", ErrDiscountUsed},
		{"other customer", "globex", nil},
	}
	for _, s := range steps {
		t.Run(s.name, func(t *testing.T) {
			_, err := c.Invoice("", s.customer, "ZERO", lines, d)
			if !errors.Is(err, s.wantErr) {
				t.Errorf("Invoice(%s) error = %v, want %v", s.customer, err, s.wantErr)
			}
		})
	}
}

func TestFailedInvoiceDoesNotBurnCode(t *testing.T) {
	c := newCalc()
	lines := []Line{{SKU: "a", Quantity: 1, UnitCents: 1000}}
	d := &Discount{Code: "KEEP", Kind: DiscountFixed, Value: 100}
	if _, err := c.Invoice("", "acme", "NOWHERE", lines, d); !errors.Is(err, ErrUnknownRegion) {
		t.Fatalf("Invoice in unknown region error = %v, want %v", err, ErrUnknownRegion)
	}
	if _, err := c.Invoice("", "acme", "FR", lines, d); err != nil {
		t.Errorf("Invoice after failed attempt error = %v, want nil", err)
	}
}

func TestInvoiceTax(t *testing.T) {
	tests := []struct {
		name      string
		region    string
		unit      int64
		d         *Discount
		wantTax   int64
		wantGrand int64
		wantErr   error
	}{
		{"fr", "FR", 1000, nil, 200, 1200, nil},
		{"de", "DE", 1000, nil, 190, 1190, nil},
		{"us-ca rounds half up", "US-CA", 200, nil, 15, 215, nil},
		{"us-ca rounds down", "US-CA", 100, nil, 7, 107, nil},
		{"tax after discount", "FR", 1000, &Discount{Code: "H", Kind: DiscountPercent, Value: 5000}, 100, 600, nil},
		{"zero rate", "ZERO", 1000, nil, 0, 1000, nil},
		{"fully discounted", "FR", 1000, &Discount{Code: "H", Kind: DiscountFixed, Value: 5000}, 0, 0, nil},
		{"unknown region", "XX", 1000, nil, 0, 0, ErrUnknownRegion},
		{"empty region", "", 1000, nil, 0, 0, ErrUnknownRegion},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			inv, err := newCalc().Invoice("i", "acme", tt.region, []Line{{SKU: "a", Quantity: 1, UnitCents: tt.unit}}, tt.d)
			if !errors.Is(err, tt.wantErr) {
				t.Fatalf("Invoice(%q) error = %v, want %v", tt.region, err, tt.wantErr)
			}
			if err != nil {
				return
			}
			if inv.TaxCents != tt.wantTax || inv.GrandTotalCents != tt.wantGrand {
				t.Errorf("Invoice(%q) tax, grand = %d, %d; want %d, %d", tt.region, inv.TaxCents, inv.GrandTotalCents, tt.wantTax, tt.wantGrand)
			}
		})
	}
}

func TestInvoiceValidation(t *testing.T) {
	tests := []struct {
		name     string
		customer string
		lines    []Line
		wantErr  error
	}{
		{"no customer", "", nil, ErrNoCustomer},
		{"negative quantity", "acme", []Line{{SKU: "a", Quantity: -1, UnitCents: 1}}, ErrInvalidLine},
		{"negative price", "acme", []Line{{SKU: "a", Quantity: 1, UnitCents: -1}}, ErrInvalidLine},
		{"no lines", "acme", nil, nil},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := newCalc().Invoice("i", tt.customer, "FR", tt.lines, nil)
			if !errors.Is(err, tt.wantErr) {
				t.Errorf("Invoice(%q) error = %v, want %v", tt.customer, err, tt.wantErr)
			}
		})
	}
}

func TestWriteCSV(t *testing.T) {
	inv := Invoice{
		ID: "i1", Customer: "ac,me", Region: "US-CA", IssuedAt: testNow,
		TotalCents: 1000, DiscountCents: 100, TaxCents: 65, GrandTotalCents: 965,
	}
	header := "id,customer,region,issued_at,total_cents,discount_cents,tax_cents,grand_total_cents\n"
	tests := []struct {
		name string
		in   []Invoice
		want string
	}{
		{"empty", nil, header},
		{"one", []Invoice{inv}, header + "i1,\"ac,me\",US-CA,2026-03-01T12:00:00Z,1000,100,65,965\n"},
		{"two", []Invoice{inv, {ID: "i2", Customer: "b", Region: "FR", IssuedAt: testNow}}, header +
			"i1,\"ac,me\",US-CA,2026-03-01T12:00:00Z,1000,100,65,965\n" +
			"i2,b,FR,2026-03-01T12:00:00Z,0,0,0,0\n"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var buf bytes.Buffer
			if err := WriteCSV(context.Background(), &buf, tt.in); err != nil {
				t.Fatalf("WriteCSV(%s) error = %v", tt.name, err)
			}
			if got := buf.String(); got != tt.want {
				t.Errorf("WriteCSV(%s) = %q, want %q", tt.name, got, tt.want)
			}
		})
	}
}

func TestWriteCSVCancelled(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	var buf bytes.Buffer
	err := WriteCSV(ctx, &buf, []Invoice{{ID: "i1"}})
	if !errors.Is(err, context.Canceled) {
		t.Errorf("WriteCSV with cancelled ctx error = %v, want %v", err, context.Canceled)
	}
	if strings.Count(buf.String(), "\n") > 1 {
		t.Errorf("WriteCSV with cancelled ctx wrote rows: %q", buf.String())
	}
}

